describe('Filtered Search URL Sharing', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should successfully share a filtered search URL with another user', () => {
    // Setup: Navigate to search page and perform a search
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();

    // Verify search results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('contain', 'laptop');

    // Apply a filter (e.g., price range)
    cy.get('[data-testid="price-filter"]').click();
    cy.get('[data-testid="price-range-selector"]').click();
    cy.get('[data-testid="price-range-option"]').eq(1).click();

    // Verify filter is applied
    cy.get('[data-testid="filter-status"]').should('contain', 'Price: $1000 - $2000');

    // Share the filtered search URL
    cy.get('[data-testid="share-button"]').click();

    // Verify share modal appears
    cy.get('[data-testid="share-modal"]').should('be.visible');

    // Fill share form with recipient's email
    cy.get('[data-testid="recipient-email-input"]').type('test@example.com');

    // Verify share button is enabled
    cy.get('[data-testid="share-button"]').should('be.visible');

    // Click share button
    cy.get('[data-testid="share-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Search URL shared successfully');

    // Verify URL is visible in the success message
    cy.get('[data-testid="success-message"]').should('contain', 'https://example.com/search?q=laptop&price=1000-2000');
  });

  it('should handle edge case when sharing a filtered search URL fails', () => {
    // Setup: Navigate to search page and perform a search
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();

    // Verify search results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');

    // Apply a filter
    cy.get('[data-testid="price-filter"]').click();
    cy.get('[data-testid="price-range-option"]').eq(1).click();

    // Verify filter is applied
    cy.get('[data-testid="filter-status"]').should('contain', 'Price: $1000 - $2000');

    // Attempt to share the filtered search URL
    cy.get('[data-testid="share-button"]').click();

    // Verify share modal appears
    cy.get('[data-testid="share-modal"]').should('be.visible');

    // Fill share form with invalid recipient's email (e.g., no '@')
    cy.get('[data-testid="recipient-email-input"]').type('invalid-email');

    // Verify share button is disabled
    cy.get('[data-testid="share-button"]').should('be.disabled');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid recipient email');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});
